export function PlatformMark({ platform }: { platform: ReviewPlatform }) {
  switch (platform) {
    case "Google":
      return <GoogleMark />;
    case "Airbnb":
      return <AirbnbMark />;
    case "Agoda":
      return <AgodaMark />;
    case "MakeMyTrip":
      return <MakeMyTripLogo className="h-3.5 w-auto" />;
  }
}

// Self-contained OTA badge: an icon+name pill for Google/Airbnb/Agoda, or
// MakeMyTrip's own lockup alone (it already spells out the brand name, so
// pairing it with a second "MAKEMYTRIP" text label would just repeat it).
export function OTABadge({ platform, className }: { platform: ReviewPlatform; className?: string }) {
  if (platform === "MakeMyTrip") {
    return (
      <span
        className={`inline-flex shrink-0 items-center rounded-full px-2 py-1 ring-1 ring-inset ${PLATFORM_STYLE.MakeMyTrip} ${className ?? ""}`}
      >
        <MakeMyTripLogo className="h-4 w-auto" />
      </span>
    );
  }
  return (
    <span
      className={`inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide ring-1 ring-inset ${PLATFORM_STYLE[platform]} ${className ?? ""}`}
    >
      <PlatformMark platform={platform} />
      {platform}
    </span>
  );
}
